import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"30、【离】 离下离上","description":"周易尚氏学 - 30、【离】 离下离上","frontmatter":{"title":"30、【离】 离下离上","description":"周易尚氏学 - 30、【离】 离下离上"},"headers":[],"relativePath":"zh/classics/shangshi/035.md","filePath":"zh/classics/shangshi/035.md"}'),h={name:"zh/classics/shangshi/035.md"};function s(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_30、【离】-离下离上" tabindex="-1">30、【离】 离下离上 <a class="header-anchor" href="#_30、【离】-离下离上" aria-label="Permalink to “30、【离】 离下离上”">​</a></h1><p>乾交坤为坎。坤交乾为离。坎为隐而离则明矣。凡相对之卦。其义皆对。二五中正。故利贞。二五丽于阳中故亨。坤为牛。离得坤中爻。故亦为牛。俞云。说文牝畜母也。牧牛即母牛。虞翻谓以离为牝牛为借说。岂知左传昭五年。明云纯离为牛。由是证虞翻未见左氏。</p><p>象曰。离。丽也。日月丽乎天。百谷草木丽乎土。重明以丽乎正。及化成天下。柔丽乎中正。故亨。是以畜牝牛吉也。</p><p>五为天位。离日兑月。象失传。详焦氏易诂皆在五。故曰日月丽乎天。礼王制邮罚丽于事。注丽附也。言日月附于天也。二四互巽。为百谷。为草木。而二为地位。故曰丽乎地。从王肃不作土两象故重明。万物得日以化成。</p><p>象曰。明两作。离。大人以继明照于四方。</p><p>晌明而治。故曰大人。重明。故曰继。</p><p>初九。履错然。敬之。句无咎。</p><p>王注。错然敬慎之貌。处离之始。故宜慎所履以敬为务。避其咎也。按初为震爻。震为履。错然。盖又有郑重不苟之意。故曰敬。以敬之连无咎读者非。</p><h3 id="象曰。履错之敬。以辟咎也。" tabindex="-1">象曰。履错之敬。以辟咎也。 <a class="header-anchor" href="#象曰。履错之敬。以辟咎也。" aria-label="Permalink to “象曰。履错之敬。以辟咎也。”">​</a></h3><p>六二。黄离。元吉。</p><p>坤色黄。离得坤中爻。故曰黄离。得中故大吉。</p><h3 id="象曰。黄离元吉。得中道也。" tabindex="-1">象曰。黄离元吉。得中道也。 <a class="header-anchor" href="#象曰。黄离元吉。得中道也。" aria-label="Permalink to “象曰。黄离元吉。得中道也。”">​</a></h3><p>九三。日昃之离。不鼓击而歌。则大耋之嗟。凶。</p><p>三居离终。故曰日昃。故象曰不可久。此爻全用伏象。伏震为鼓为缶为歌。伏艮为坚。故易林常以艮为寿为老。释言耋老也。盖三居下卦之终。时已迟暮。故曰不鼓缶而歌。诗坎其系击。缶固古乐也。而三居互艮之初。艮为大老？？？。言不及时行乐。则将有衰老之嗟也。震为乐。震反为艮则嗟矣。此与中孚六三之或鼓或罢。或泣或歌。皆正覆象并用。与杂卦震起艮止。兑见巽伏之义同也。而能识此旨者。在古则左传。在西汉则易林。后则无知者。</p><h3 id="象曰。日昃之离。何可久也。" tabindex="-1">象曰。日昃之离。何可久也。 <a class="header-anchor" href="#象曰。日昃之离。何可久也。" aria-label="Permalink to “象曰。日昃之离。何可久也。”">​</a></h3><p>九四。突如其来如。焚如。死如。弃如。</p><p>九四虽失位。然其凶不至如此之甚。盖此爻之义。仍取覆象。自覆象失传。故说者皆莫明其故。离二至四巽。巽顺。三至五巽覆。即不顺矣。兑刚卤。故突如其来如。突与云同。亦作充（下　？）。说文云不顺忽出也。从倒子。易曰突如其来如。不孝子突出不容于内也。云亦作充（下　）者。说文充（下　）下云。或从倒古文子。即易突字。按古文子作灾。倒之即为充（下　）。惠栋校集解。竟改为充（下　）。然说文明曰即易突字。是古本易作突与今同。改作灾非也。巽覆故不顺。子体倒故曰不孝子。不孝子无所容于世。体离故焚如。兑毁折故死如。弃如。说文弃损也。从充（下　）。充（下　）不孝子也。故匈奴传。王莽造焚如之刑。如淳云。焚如死如弃如者。谓不孝子也。不畜于父母。不容于朋友。故烧杀弃之。按如淳及许慎之说。皆与象传无所容义合。盖古义如此也。</p><h3 id="象曰。突如其来如。无所容也。" tabindex="-1">象曰。突如其来如。无所容也。 <a class="header-anchor" href="#象曰。突如其来如。无所容也。" aria-label="Permalink to “象曰。突如其来如。无所容也。”">​</a></h3><p>六五。出涕沦若。戚嗟若。吉。</p><p>目汁出曰涕。五离为目。兑为雨水。夬九三。往遇雨。革传水火相息。水出自目。故曰涕沦。沦说文水别流。言涕被面而支溢也。清儒皆以伏坎为涕。于卦象之神妙全失。兑口为嗟。若者语辞。象本不吉。然而云吉者。以丽于阳中也。</p><h3 id="象曰。六五之吉。丽王公也。" tabindex="-1">象曰。六五之吉。丽王公也。 <a class="header-anchor" href="#象曰。六五之吉。丽王公也。" aria-label="Permalink to “象曰。六五之吉。丽王公也。”">​</a></h3><p>乾为王为公。谓四上。</p><p>上九。王用出征，有嘉折首，获匪其丑，无咎。</p><p>此与大有鼎上九义同也。大有上九云。自天有之。吉无不利。鼎上九云。大吉。盖大有鼎中交皆不利。凡中爻不通利者。上九必利。大畜中爻为艮所畜。至上九忽亨。则以上九高出庶物。不为所言也。大有鼎离与大畜理同也。茹敦和云。离有征伐象。明夷九三日。南狩（左月）。得其大首。晋上九日。维有伐邑。皆为离上爻。盖一阳突出兑说之上。而兑为斧钺。离为甲兵。故曰王用出征。兑为毁折。乾为首。先儒皆谓坎折坤。则离亦折乾也。皆以中爻故离有杀象。既济云东邻杀牛是也。折首谓杀敌。于思泊云。虢季盘折首五百。执讯五十。不？（左其右上凤右下女）股。女多禽折首。执讯。征之金文。皆谓杀敌。非谓魁首。按于说是也。匪与分古通。周礼地官。凛（？）人以待国之匪颁。注匪读为分。获匪其卫者。谓匪颁所获丑掳于有功。以为奴隶也。</p><h3 id="象曰。王用出征。以正邦也。" tabindex="-1">象曰。王用出征。以正邦也。 <a class="header-anchor" href="#象曰。王用出征。以正邦也。" aria-label="Permalink to “象曰。王用出征。以正邦也。”">​</a></h3><p>征正也。折首获丑。皆正邦之事。邦象未详。诸家皆以坤为邦。按三至五伏艮。艮为邦。</p>',26)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
